const genericFields={requests:['Person Type','Person','Request Type','From Date','To Date','Reason','Status','Admin Remarks'],homework:['Class','Subject','Teacher','Homework Date','Due Date','Homework','Attachment URL','Status'],timetable:['Date','Class','Subject','Teacher','Start Time','End Time'],welfare:['Date','Student','Item','Quantity','Remarks'],inventory:['Item','Category','Quantity','Unit','Status','Remarks'],exams:['Exam Name','Class','Subject','Exam Date','Maximum Marks','Remarks'],certificates:['Student','Certificate Type','Issue Date','Certificate No.','Remarks'],svcet:['Student Name','Class','School','Exam Date','Marks','Rank','Selection Status'],ptm:['Date','Student','Guardian','Teacher','Discussion','Remarks'],holidays:['Date','Holiday Name','Remarks'],schoolProfile:['Centre Name','Centre Code','Session','Mobile','Email','Address'],adminProfile:['Name','Mobile','Email','Username']};
const fixedOptions={'Person Type':['Student','Teacher'],'Request Type':['Leave','Other Issue'],'Selection Status':['Selected','Not Selected','Waiting'],'Unit':['Piece','Set','Box','Kg','Litre','Other'],'Class':['5']};
function fieldControl(route,f,v=''){let q=esc(v||''),opts=fixedOptions[f];if(f==='Status')opts=route==='requests'?['Pending','Approved','Rejected']:route==='homework'?['Published','Archived']:route==='inventory'?['Available','Low Stock','Out of Stock']:['Active','Inactive'];if(f==='Student')opts=db.students.map(x=>x.name);if(f==='Teacher')opts=db.teachers.map(x=>x.name);if(f==='Person')opts=[...db.students,...db.teachers].map(x=>x.name);if(f==='Certificate Type')opts=['Achievement','Participation','Bonafide','Other'];if(opts&&opts.length)return `<select name="${f}">${opts.map(x=>`<option ${String(v)===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`;if(/Date/i.test(f))return `<input type="date" name="${f}" value="${q}">`;if(/Start Time|End Time/i.test(f))return `<input type="time" name="${f}" value="${q}">`;if(/Remarks|Description|Discussion|Address|Reason|Homework/i.test(f))return `<textarea name="${f}">${q}</textarea>`;return `<input name="${f}" value="${q}">`}
function generic(route){
 if(route==='settings')return settingsPage();
 if(route==='requests')return requestsAdmin();
 if(route==='homework')return homeworkAdmin();
 let title=route.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase()),fields=genericFields[route]||['Title','Date','Description'],rows=db.generic[route]||[];
 app.innerHTML=shell(title,`<div class="panel tint"><button class="btn green" onclick="SV.genericForm('${route}')">+ Add ${esc(title)}</button></div><div class="panel">${rows.map((r,i)=>`<div class="listitem"><div class="grow"><b>${esc(genericValue(route,r,fields[0])||r[Object.keys(r)[1]]||title)}</b><small style="display:block">${esc(fields.slice(1,3).map(f=>{let v=genericValue(route,r,f)||'';return /Date/i.test(f)?fmtDate(v):v}).filter(Boolean).join(' • '))}</small></div><button class="btn primary" onclick="SV.genericForm('${route}',${i})">Edit</button><button class="btn danger" onclick="SV.deleteGeneric('${route}',${i})">Delete</button></div>`).join('')||'No records yet.'}</div>`)
}
function requestsAdmin(){let hi=localStorage.getItem('sv_lang')==='hi',rows=db.generic.requests||[];app.innerHTML=shell(hi?'अनुरोध':'Requests',`<div class="panel">${rows.map((r,i)=>`<div class="listitem"><div class="grow"><b>${esc(r.personName||r.Person||r.personId||'')}</b><small style="display:block">${esc(r.requestType||r['Request Type']||'')} • ${fmtDate(r.fromDate||r['From Date'])} - ${fmtDate(r.toDate||r['To Date'])} • ${esc(r.status||r.Status||'Pending')}</small></div><button class="btn primary" onclick="SV.viewRequest(${i})">${hi?'देखें':'View'}</button>${String(r.status||r.Status||'Pending').toLowerCase()==='pending'?`<button class="btn green" onclick="SV.setRequestStatus(${i},'Approved')">${hi?'स्वीकृत':'Approve'}</button><button class="btn danger" onclick="SV.setRequestStatus(${i},'Rejected')">${hi?'अस्वीकृत':'Reject'}</button>`:''}</div>`).join('')||(hi?'अभी कोई अनुरोध नहीं है।':'No requests yet.')}</div>`)}
function viewRequest(i){let hi=localStorage.getItem('sv_lang')==='hi',r=(db.generic.requests||[])[i];if(!r)return;let labels=hi?{personName:'व्यक्ति',requestType:'अनुरोध प्रकार',fromDate:'आरंभ तिथि',toDate:'अंतिम तिथि',reason:'कारण',status:'स्थिति',adminRemarks:'प्रशासक टिप्पणी'}:{personName:'Person',requestType:'Request Type',fromDate:'From Date',toDate:'To Date',reason:'Reason',status:'Status',adminRemarks:'Admin Remarks'};let keys=['personName','requestType','fromDate','toDate','reason','status','adminRemarks'];document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="reqView"><div class="sheet"><h3>${hi?'अनुरोध विवरण':'Request Details'}</h3>${keys.map(k=>`<div class="detail"><b>${labels[k]}</b>${esc(/Date/.test(k)?fmtDate(r[k]):r[k]||'—')}</div>`).join('')}<button class="btn" style="margin-top:12px" onclick="SV.closeModal('reqView')">${hi?'बंद करें':'Close'}</button></div></div>`)}
async function setRequestStatus(i,status){let r={...(db.generic.requests||[])[i],status};let res=await api('upsertModuleRecord',{module:'requests',index:i,record:r});if(!res.ok)return showPopup(res.message||'Unable to update request.','error');await syncData(true);requestsAdmin();showPopup(localStorage.getItem('sv_lang')==='hi'?(status==='Approved'?'अनुरोध स्वीकृत किया गया।':'अनुरोध अस्वीकृत किया गया।'):(status==='Approved'?'Request approved.':'Request rejected.'),'success')}
function homeworkAdmin(){let hi=localStorage.getItem('sv_lang')==='hi',rows=db.generic.homework||[];app.innerHTML=shell(hi?'गृहकार्य':'Homework',`<div class="panel">${rows.map((r,i)=>`<div class="listitem"><div class="grow"><b>${esc(r.subject||r.Subject||'')}</b><small style="display:block">${esc(r.className||r.Class||'')} • ${esc(r.teacherName||r.Teacher||'')} • ${fmtDate(r.homeworkDate||r['Homework Date'])}</small><div style="margin-top:5px">${esc(r.homework||r.Homework||'')}</div></div></div>`).join('')||(hi?'अभी कोई गृहकार्य नहीं है।':'No homework yet.')}</div>`) }

function genericForm(route,idx){let fields=genericFields[route]||['Title','Date','Description'],r=(db.generic[route]||[])[idx]||{};document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="genModal"><div class="sheet"><h3>${idx==null?'Add':'Edit'} ${route.replace(/([A-Z])/g,' $1')}</h3><form id="gf">${fields.map(f=>`<label class="f">${f}${fieldControl(route,f,genericValue(route,r,f))}</label>`).join('')}<div class="row" style="margin-top:10px"><button class="btn green">Save</button><button type="button" class="btn" onclick="SV.closeModal('genModal')">Cancel</button></div></form></div></div>`);$('#gf').onsubmit=async e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target)),res=await api('upsertModuleRecord',{module:route,index:idx,record:o});if(!res.ok)return showPopup(res.message||'Unable to save.','error');await syncData(true);closeModal('genModal');generic(route);toast('Saved successfully','success')}}

async function deleteGeneric(route,idx){if(!await confirmPopup('Delete this record?'))return;let r=await api('deleteModuleRecord',{module:route,index:idx});if(!r.ok)return showPopup(r.message||'Unable to delete.','error');(db.generic[route]||[]).splice(idx,1);save();generic(route);showPopup('Record deleted successfully.','success')}
