function applyLanguage(){if(localStorage.getItem('sv_lang')!=='hi')return;document.documentElement.lang='hi';const root=document.getElementById('app');if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{let raw=n.nodeValue,trim=raw.trim();if(!trim)return;let out=HI[trim];if(!out){out=trim;for(const [en,hi] of Object.entries(HI))out=out.replaceAll(en,hi)}if(out!==trim)n.nodeValue=raw.replace(trim,out)});root.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{let p=el.getAttribute('placeholder');if(HI[p])el.setAttribute('placeholder',HI[p])});root.querySelectorAll('[aria-label]').forEach(el=>{let a=el.getAttribute('aria-label');if(HI[a])el.setAttribute('aria-label',HI[a])})}
let langBusy=false;new MutationObserver(()=>{if(langBusy||localStorage.getItem('sv_lang')!=='hi')return;langBusy=true;requestAnimationFrame(()=>{applyLanguage();langBusy=false})}).observe(app,{childList:true,subtree:true});
